// ============================================================
// DOMPurify - حماية من هجمات XSS
// نسخة مبسطة وسريعة
// ============================================================

(function(global) {
    'use strict';

    // قائمة العلامات المسموحة
    const ALLOWED_TAGS = [
        'p', 'br', 'b', 'i', 'u', 's', 'strong', 'em', 'mark',
        'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
        'ul', 'ol', 'li', 'blockquote', 'pre', 'code',
        'a', 'img', 'span', 'div', 'section', 'article',
        'table', 'thead', 'tbody', 'tr', 'td', 'th'
    ];

    // قائمة السمات المسموحة
    const ALLOWED_ATTRS = [
        'href', 'src', 'alt', 'title', 'class', 'id',
        'style', 'width', 'height', 'target', 'rel'
    ];

    // دوال الحماية
    function sanitize(dirty) {
        if (typeof dirty !== 'string') return '';
        if (!dirty) return '';

        // إزالة أي شيء يشبه كود خبيث
        let clean = dirty
            .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, '')
            .replace(/<iframe[\s\S]*?>[\s\S]*?<\/iframe>/gi, '')
            .replace(/<object[\s\S]*?>[\s\S]*?<\/object>/gi, '')
            .replace(/<embed[\s\S]*?\/>/gi, '')
            .replace(/<link[\s\S]*?>/gi, '')
            .replace(/<meta[\s\S]*?>/gi, '')
            .replace(/on\w+=/gi, 'data-removed-')
            .replace(/javascript:/gi, 'blocked:')
            .replace(/data:text\/html/gi, 'blocked:')
            .replace(/vbscript:/gi, 'blocked:')
            .replace(/expression\(/gi, 'blocked(')
            .replace(/eval\(/gi, 'blocked(')
            .replace(/alert\(/gi, 'blocked(')
            .replace(/confirm\(/gi, 'blocked(')
            .replace(/prompt\(/gi, 'blocked(');

        // تنقية إضافية باستخدام DOM
        const temp = document.createElement('div');
        temp.textContent = clean;
        clean = temp.innerHTML;

        return clean;
    }

    // تصدير الدالة
    global.DOMPurify = {
        sanitize: sanitize,
        addHook: function() {},
        removeHook: function() {},
        removeAllHooks: function() {},
        isValidAttribute: function() { return true; }
    };

})(window);

console.log('🛡️ DOMPurify loaded successfully');
